ssures&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Mots_de_changements_8&quot;&gt;Mots de changements&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Mot_de_climat_9&quot;&gt;Mot de climat&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Mots_de_commandement_10&quot;&gt;Mots de commandement&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Mots_de_convocation_11&quot;&gt;Mots de convocation&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Mots_de_corps_12&quot;&gt;Mots de corps&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Mots_de_destruction_13&quot;&gt;Mots de destruction&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Mots_de_d&#233;tection_14&quot;&gt;Mots de d&#233;tection&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Mots_de_dissimulation_15&quot;&gt;Mots de dissimulation&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Mots_de_dissipation_16&quot;&gt;Mots de dissipation&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Mots_de_divination_17&quot;&gt;Mots de divination&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Mots_de_douleur_18&quot;&gt;Mots de douleur&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Mots_de_feu_19&quot;&gt;Mots de feu&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Mots_de_force_20&quot;&gt;Mots de force&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Mots_de_froid_21&quot;&gt;Mots de froid&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Mots_de_gravit&#233;_22&quot;&gt;Mots de gravit&#233;&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Mots_de_gu&#233;rison_23&quot;&gt;Mots de gu&#233;rison&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Mots_de_langage_24&quot;&gt;Mots de langage&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Mots_de_liens_25&quot;&gt;Mots de liens&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Mots_de_mort_26&quot;&gt;Mots de mort&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Mots_de_mur_27&quot;&gt;Mots de mur&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Mots_de_peur_28&quot;&gt;Mots de peur&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Mots_de_pouvoir_29&quot;&gt;Mots de pouvoir&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Mots_de_son_30&quot;&gt;Mots de son&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Mots_de_t&#233;l&#233;portation_31&quot;&gt;Mots de t&#233;l&#233;portation&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Mots_de_temps_32&quot;&gt;Mots de temps&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Mots_de_vie_33&quot;&gt;Mots de vie&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Mots_de_vol_34&quot;&gt;Mots de vol&lt;/a&gt;&lt;br /&gt;&lt;/p&gt;&lt;/div&gt;&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la magie (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Magic/Art de la Magie&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUM.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;Les &lt;a class=&quot;pagelink&quot; href=&quot;Mots-Effets.html&quot; title=&quot;Les mots effets&quot;&gt;mots effets&lt;/a&gt; d&#233;terminent le r&#233;sultat global d’un sort de mots. Celui-ci peut comporter plusieurs &lt;a class=&quot;pagelink&quot; href=&quot;Mots-Effets.html&quot; title=&quot;Les mots effets&quot;&gt;mots effets&lt;/a&gt; et il est possible que certains s’annulent mutuellement. Les &lt;a class=&quot;pagelink&quot; href=&quot;Mots-Effets.html&quot; title=&quot;Les mots effets&quot;&gt;mots effets&lt;/a&gt; sont pr&#233;sent&#233;s selon le format suivant.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Nom.&lt;/b&gt; C’est le nom du &lt;a class=&quot;pagelink&quot; href=&quot;Mots-Effets.html&quot; title=&quot;Les mots effets&quot;&gt;mot effet&lt;/a&gt;. Il appartient &#224; un groupe de mots similaires, indiqu&#233; entre parenth&#232;ses. Sauf indication contraire, un sort de mots ne peut comporter deux &lt;a class=&quot;pagelink&quot; href=&quot;Mots-Effets.html&quot; title=&quot;Les mots effets&quot;&gt;mots effets&lt;/a&gt; du m&#234;me groupe.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;&#201;cole.&lt;/b&gt; Cette ligne indique l’&#233;cole de magie &#224; laquelle le &lt;a class=&quot;pagelink&quot; href=&quot;Mots-Effets.html&quot; title=&quot;Les mots effets&quot;&gt;mot effet&lt;/a&gt; appartient.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Niveau.&lt;/b&gt; Cette ligne indique les &lt;a class=&quot;pagelink&quot; href=&quot;Classes.html&quot; title=&quot;Les classes&quot;&gt;classes&lt;/a&gt; qui peuvent apprendre le &lt;a class=&quot;pagelink&quot; href=&quot;Mots-Effets.html&quot; title=&quot;Les mots effets&quot;&gt;mot effet&lt;/a&gt; et son niveau pour les membres de ces &lt;a class=&quot;pagelink&quot; href=&quot;Classes.html&quot; title=&quot;Les classes&quot;&gt;classes&lt;/a&gt;. Notez qu’un sort de mots ne peut comporter de mot dont le niveau est sup&#233;rieur &#224; celui du sort.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Dur&#233;e.&lt;/b&gt; Cette ligne indique la dur&#233;e du &lt;a class=&quot;pagelink&quot; href=&quot;Mots-Effets.html&quot; title=&quot;Les mots effets&quot;&gt;mot effet&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Jet de sauvegarde.&lt;/b&gt; Si l’effet autorise un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jet de sauvegarde&lt;/a&gt;, il sera indiqu&#233; ici, ainsi que les effets en cas de r&#233;ussite.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;R&#233;sistance &#224; la magie.&lt;/b&gt; Si le &lt;a class=&quot;pagelink&quot; href=&quot;Mots-Effets.html&quot; title=&quot;Les mots effets&quot;&gt;mot effet&lt;/a&gt; autorise la &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-&#192;-La-Magie-(Capacit&#233;).html&quot; title=&quot;R&#233;sistance &#224; la magie&quot;&gt;r&#233;sistance &#224; la magie&lt;/a&gt;, elle sera indiqu&#233;e ici.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Restrictions de cible.&lt;/b&gt; Certains &lt;a class=&quot;pagelink&quot; href=&quot;Mots-Effets.html&quot; title=&quot;Les mots effets&quot;&gt;mots effets&lt;/a&gt; ne peuvent &#234;tre combin&#233;s qu’avec des &lt;a class=&quot;pagelink&quot; href=&quot;Mots-Cibles.html&quot; title=&quot;Les mots cibles&quot;&gt;mots cibles&lt;/a&gt; sp&#233;cifiques. Si c’est le cas, les &lt;a class=&quot;pagelink&quot; href=&quot;Mots-Cibles.html&quot; title=&quot;Les mots cibles&quot;&gt;mots cibles&lt;/a&gt; concern&#233;s sont indiqu&#233;s ici.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Description.&lt;/b&gt; Ce paragraphe d&#233;crit les effets d’un mot lorsqu’il est arrang&#233; dans un sort de mots.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Augmentation.&lt;/b&gt; Si le &lt;a class=&quot;pagelink&quot; href=&quot;Mots-Cibles.html&quot; title=&quot;Les mots cibles&quot;&gt;mot cible&lt;/a&gt; peut &#234;tre am&#233;lior&#233; par le &lt;a class=&quot;pagelink&quot; href=&quot;M&#233;ta-Mots.html&quot; title=&quot;Les m&#233;ta mots&quot;&gt;m&#233;ta mot&lt;/a&gt; &lt;i&gt;augmentation&lt;/i&gt;, les effets sont list&#233;s ici. Reportez-vous &#224; la section consacr&#233;e aux &lt;a class=&quot;pagelink&quot; href=&quot;M&#233;ta-Mots.html&quot; title=&quot;Les m&#233;ta mots&quot;&gt;m&#233;ta mots&lt;/a&gt; pour plus de d&#233;tails&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Types de mots effets&lt;a class=&quot;headeranchor&quot; id=&quot;Types_de_mots_effets_35&quot; href=&quot;#Types_de_mots_effets_35&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;MOTSDACIDE&quot; href=&quot;#MOTSDACIDE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Mots d’acide&lt;a class=&quot;headeranchor&quot; id=&quot;Mots_d’acide_0&quot; href=&quot;#Mots_d’acide_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Ces mots cr&#233;ent un acide corrosif qui ronge et br&#251;le tout ce avec quoi il entre en contact.
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Br&#251;lure-Acide.html&quot; title=&quot;Br&#251;lure acide&quot;&gt;Br&#251;lure acide&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;clair-Corrosif.html&quot; title=&quot;&#201;clair corrosif&quot;&gt;&#201;clair corrosif&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Nuage-Corrosif.html&quot; title=&quot;Nuage corrosif&quot;&gt;Nuage corrosif&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vague-Acide.html&quot; title=&quot;Vague acide&quot;&gt;Vague acide&lt;/a&gt;&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;MOTSDALIGNEMENT&quot; href=&quot;#MOTSDALIGNEMENT&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Mots d’alignement&lt;a class=&quot;headeranchor&quot; id=&quot;Mots_d’alignement_1&quot; href=&quot;#Mots_d’alignement_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les mots de cette famille ont un rapport direct avec l’alignement, d&#233;tectant, infligeant des d&#233;g&#226;ts ou prot&#233;geant les cr&#233;atures selon leur inclinaison morale.
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Assaut-Dalignement.html&quot; title=&quot;Assaut d&amp;#39;alignement&quot;&gt;Assaut d&#39;alignement&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Aura-Dalignement.html&quot; title=&quot;Aura d&amp;#39;alignement&quot;&gt;Aura d&#39;alignement&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-Dalignement.html&quot; title=&quot;Bouclier d&amp;#39;alignement&quot;&gt;Bouclier d&#39;alignement&lt;/a&gt;&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;MOTSDANIMAL&quot; href=&quot;#MOTSDANIMAL&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Mots d’animal&lt;a class=&quot;headeranchor&quot; id=&quot;Mots_d’animal_2&quot; href=&quot;#Mots_d’animal_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les mots de cette famille parlent directement aux cr&#233;atures sauvages, les calmant et les contr&#244;lant.
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Appel-Sauvage.html&quot; title=&quot;Appel sauvage&quot;&gt;Appel sauvage&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Calme-De-La-Nature.html&quot; title=&quot;Calme de la nature&quot;&gt;Calme de la nature&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Commandement-De-La-Nature.html&quot; title=&quot;Commandement de la nature&quot;&gt;Commandement de la nature&lt;/a&gt;&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;MOTSDARMURE&quot; href=&quot;#MOTSDARMURE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Mots d’armure&lt;a class=&quot;headeranchor&quot; id=&quot;Mots_d’armure_3&quot; href=&quot;#Mots_d’armure_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Ces mots cr&#233;ent une armure translucide faite de magie solide, qui prot&#232;ge sans &#234;tre un poids ni un obstacle.
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Armure-De-Force.html&quot; title=&quot;Armure de force&quot;&gt;Armure de force&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Blocage-De-Force.html&quot; title=&quot;Blocage de force&quot;&gt;Blocage de force&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-De-Force.html&quot; title=&quot;Bouclier de force&quot;&gt;Bouclier de force&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Glyphe-De-Force.html&quot; title=&quot;Glyphe de force&quot;&gt;Glyphe de force&lt;/a&gt;&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;MOTSDELECTRICITE&quot; href=&quot;#MOTSDELECTRICITE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
